UPDATE products
SET name = #{name},
    storage = #{storage, jdbcType=VARCHAR},
    client_code = #{clientCode, jdbcType=VARCHAR} 
WHERE code = #{code}

UPDATE pricing
SET product_name = #{name}
WHERE product_code = #{code}

UPDATE products
SET discontinued = #{discontinued},
    discontinued_at = #{discontinuedAt, jdbcType=VARCHAR},
    discontinued_by = #{discontinuedBy, jdbcType=VARCHAR},
    discontinued_note = #{discontinuedNote, jdbcType=VARCHAR}
WHERE code = #{code}

UPDATE pricing
SET material_cost = #{materialCost},
    total_price = #{totalPrice}
WHERE product_code = #{code}
